// Laws tab > "Offence guide (BNS 2023)": common offences under the Bharatiya Nyaya Sanhita, 2023
// (in force from 1 July 2024, replacing the IPC), each with a simple title and a one-line simple
// explanation in English, Telugu and Hindi. Static, written by hand from the official BNS text
// (India Code) - NOT generated by AI at run time.
//
// The legal facts shown with each entry (section, official offence text, punishment, cognizable,
// bailable, court, old IPC section) are NOT here: they come from the official BNSS First Schedule
// rows in bns.generated.ts (every row whose BNS section number is in `bases`), so they stay exactly
// as published. Telugu / Hindi lines are translations to help the reader; the official English text
// prevails. Not legal advice.
//
// Sources:
//   BNS 2023 text:          https://www.indiacode.nic.in/handle/123456789/20062
//   BNSS 2023 text:         https://www.indiacode.nic.in/handle/123456789/20099
//   BNSS First Schedule:    https://www.ncrb.mha.gov.in/uploads/SankalanPortal/ScheduleBNSS.html

export type Tri = { en: string; te: string; hi: string };

export type OffenceCategory = 'body' | 'women' | 'children' | 'property' | 'money' | 'peace' | 'words' | 'road' | 'state';

export interface OffenceEntry {
  id: string;
  cat: OffenceCategory;
  bases: number[]; // BNS section numbers; every Schedule row of these sections is shown
  t: Tri; // simple title
  x: Tri; // simple explanation (what act is the offence)
  kw?: string[]; // extra search words (everyday words people use)
}

